{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 BWF / iXML Embed Tools\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Write metadata into WAV files with the BWF MetaEdit command-line tool (bwfmetaedit):\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Embed iXML and BWF Metadata from Take 1 to Active Take (with SMPTE UMID option)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Timecode Embed Tool: TimeReference to BWF + iXML, from Take 1 or the item position\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab SMPTE UMID Generate and Embed Tool (bext:UMID)\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires BWF MetaEdit: https://mediaarea.net/BWFMetaEdit (macOS: brew install bwfmetaedit).\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Item List\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Spreadsheet-style tables of items with track / take / note / source and metadata columns (metadata track name, channel number, interleave, ...).\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Item List Editor: live table of the selected items with inline editing, copy / paste and export (TSV / CSV)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Item List Browser: based on the Editor, with browsing and filtering features for larger sessions\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
